class Employee:
    def __init__(self, employee_id, name, position, department, salary):
        self.employee_id = employee_id
        self.name = name
        self.position = position
        self.department = department
        self.salary = salary

    def __eq__(self, other):
        if not isinstance(other, Employee):
            return NotImplemented
        return self.employee_id == other.employee_id

    def to_dict(self):
        return {
            'employee_ID': self.employee_id,
            'name': self.name,
            'position': self.position,
            'department': self.department,
            'salary': self.salary
        }


class HRManagementSystem:
    EMPLOYEE_FIELDS = {'name', 'position', 'department', 'salary'}

    def __init__(self):
        self._employees = {}  # {employee_id: Employee}

    def add_employee(self, employee_id, name, position, department, salary):
        if employee_id in self._employees:
            return False
        employee = Employee(employee_id, name, position, department, salary)
        self._employees[employee_id] = employee
        return True

    def remove_employee(self, employee_id):
        if employee_id not in self._employees:
            return False
        del self._employees[employee_id]
        return True

    def update_employee(self, employee_id: int, employee_info: dict):
        employee = self.get_employee(employee_id)
        if employee is None:
            return False
        if not self._is_valid_employee_info(employee_info):
            return False
        self._apply_employee_info(employee, employee_info)
        return True

    def get_employee(self, employee_id):
        return self._employees.get(employee_id)

    def list_employees(self):
        return {
            employee_id: employee.to_dict()
            for employee_id, employee in self._employees.items()
        }

    def _is_valid_employee_info(self, employee_info: dict) -> bool:
        return set(employee_info.keys()).issubset(self.EMPLOYEE_FIELDS)

    def _apply_employee_info(self, employee: Employee, employee_info: dict) -> None:
        for key, value in employee_info.items():
            setattr(employee, key, value)
